'use strict';

function ensurePlayerId(player){if(player&&!player.pid)player.pid=crypto.randomUUID();return player}
function transferQuality(player){const keys=player.keeper?['gk','pas','pos','sta']:['tec','pas','fin','tak','pos','spd','sta'];return keys.reduce((sum,key)=>sum+(player[key]||50),0)/keys.length}
function marketValue(player){const quality=transferQuality(player),ageFactor=player.age<=21?1.25:player.age<=25?1.12:player.age<=29?1:player.age<=32?.78:player.age<=35?.5:.3;return clamp(Math.round(((120+Math.max(0,quality-48)*14)*ageFactor*(player.keeper?.95:1))/10)*10,80,850)}
function saleValue(player){return Math.max(50,Math.round(marketValue(player)*.7/10)*10)}
function retirementChance(age){return age<34?0:Math.min(1,.5+(age-34)*.1)}
function activeOutfield(save=activeSave){return save.squad.filter(player=>!player.retired)}
function activeRosterSize(save=activeSave){return activeOutfield(save).length+(save.keeper&&!save.keeper.retired?1:0)}
function validMatchSquad(save=activeSave){return Boolean(save.keeper&&!save.keeper.retired&&activeOutfield(save).length>=5)}
function transferState(save=activeSave){return ensureTransfers(save).transfer}
function ensureTransfers(save){
 save.formerPlayers=save.formerPlayers||[];for(const player of[save.keeper,...save.squad])ensurePlayerId(player);
 if(!save.transfer||save.transfer.season!==save.seasonNumber)save.transfer={season:save.seasonNumber,open:false,prepared:false,offers:[],retirements:[],history:[],notice:''};
 save.transfer.offers=save.transfer.offers||[];save.transfer.retirements=save.transfer.retirements||[];save.transfer.history=save.transfer.history||[];return save
}
function makeMarketKeeper(quality,age){const identity=uniqueIdentity(),boost=(quality-70)*.55;return ensurePlayerId({n:1,name:identity.name,nation:identity.nation,age,keeper:true,line:'gk',type:'Torwart',foot:Math.random()<.2?'Links':'Rechts',gk:jitter(77+boost),pas:jitter(63+boost*.7),pos:jitter(76+boost*.9),spd:jitter(50+boost*.4),sta:jitter(78+boost*.7),form:0,fresh:100,history:[],seasons:[]})}
function makeMarketPlayer(line,quality,age){const defaults={def:{cell:26,role:-1},mid:{cell:17,role:0},att:{cell:7,role:1}},layout=defaults[line];return ensurePlayerId(playerIdentity(line,0,age,quality,layout.cell,layout.role))}
function makeOffer(kind,line,quality,age){const player=line==='gk'?makeMarketKeeper(quality,age):makeMarketPlayer(line,quality,age),fee=kind==='free'?0:marketValue(player);annualSalary(player);return{id:crypto.randomUUID(),kind,fee,player,signed:false}}
function createMarketOffers(){
 const ages=[19,21,23,25,27,29,31,33],regular=[makeOffer('regular','gk',72,pick(ages)),makeOffer('regular','def',74,pick(ages)),makeOffer('regular','def',68,pick(ages)),makeOffer('regular','mid',75,pick(ages)),makeOffer('regular','mid',69,pick(ages)),makeOffer('regular','att',76,pick(ages)),makeOffer('regular','att',70,pick(ages)),makeOffer('regular',pick(['def','mid','att']),72,pick(ages))],free=[makeOffer('free','gk',61,28+Math.floor(Math.random()*8)),makeOffer('free','def',62,24+Math.floor(Math.random()*11)),makeOffer('free','mid',63,23+Math.floor(Math.random()*12)),makeOffer('free','att',64,22+Math.floor(Math.random()*12)),makeOffer('free',pick(['def','mid','att']),60,25+Math.floor(Math.random()*10))];return[...regular,...free]
}
function careerGames(player){return sumStats(player).games||0}
function archiveFormer(player,reason,amount=0){ensurePlayerId(player);if(activeSave.formerPlayers.some(entry=>entry.player.pid===player.pid))return;activeSave.formerPlayers.push({player:structuredClone(player),reason,amount,season:activeSave.seasonNumber,careerGames:careerGames(player)})}
function normalizeLineup(){
 const active=activeOutfield(),available=new Map(active.map(player=>[player.n,player])),chosen=[];
 for(const number of activeSave.lineup||[])if(available.has(number)&&!chosen.includes(number))chosen.push(number);
 for(const player of[...active].sort((a,b)=>transferQuality(b)-transferQuality(a)))if(chosen.length<5&&!chosen.includes(player.n))chosen.push(player.n);
 if(chosen.length<5)for(const player of activeSave.squad.filter(player=>player.retired))if(chosen.length<5&&!chosen.includes(player.n))chosen.push(player.n);
 activeSave.lineup=chosen.slice(0,5)
}
function processRetirements(){
 const state=transferState();if(state.prepared)return;state.prepared=true;state.open=true;state.offers=createMarketOffers();state.retirements=[];
 for(const player of[activeSave.keeper,...activeSave.squad]){ensurePlayerId(player);const chance=retirementChance(player.age);if(chance&&Math.random()<chance){player.retired=true;player.retiredAge=player.age;player.retiredAfterSeason=activeSave.seasonNumber-1;state.retirements.push({pid:player.pid,name:player.name,age:player.age,keeper:Boolean(player.keeper),careerGames:careerGames(player)});archiveFormer(player,'Karriereende')}}
 normalizeLineup();syncLineupFromSquad()
}
function openTransferWindow(){ensureTransfers(activeSave);processRetirements();saveCurrent();renderCenter()}
function nextSquadNumber(){const used=new Set(activeSave.squad.map(player=>player.n));for(let number=2;number<100;number++)if(!used.has(number))return number;return 99}
function transferPosition(player){return player.keeper?'Torwart':lineNames[player.line]}
function scoutWord(value){return value>=79?'sehr stark':value>=72?'gut':value>=64?'solide':value>=56?'ausbaufähig':'schwach'}
function scoutingText(player){if(player.keeper)return`Torwartspiel ${scoutWord(player.gk)} · Stellungsspiel ${scoutWord(player.pos)} · Passspiel ${scoutWord(player.pas)}`;const focus=player.line==='def'?['tak','pos','pas']:player.line==='mid'?['tec','pas','sta']:['fin','tec','spd'],labels={tak:'Zweikampf',pos:'Stellungsspiel',pas:'Passspiel',tec:'Technik',sta:'Kondition',fin:'Abschluss',spd:'Tempo'};return focus.map(key=>`${labels[key]} ${scoutWord(player[key])}`).join(' · ')}
function offerDecision(offer){
 const state=transferState(),player=offer.player,oldKeeper=player.keeper?activeSave.keeper:null,keeperIncome=oldKeeper&&!oldKeeper.retired&&state.open?saleValue(oldKeeper):0,cashAfter=ensureFinance(activeSave).balance+keeperIncome-offer.fee,newPayroll=payroll()+annualSalary(player)-(oldKeeper?annualSalary(oldKeeper):0),capacity=player.keeper||activeRosterSize()<12,allowedWindow=offer.fee===0||state.open,keeperAllowed=!player.keeper||state.open||activeSave.keeper.retired;
 let reason='Verpflichten';if(offer.signed)reason='Verpflichtet';else if(!selectedSponsor())reason='Sponsor wählen';else if(!allowedWindow)reason='Transferfenster geschlossen';else if(!keeperAllowed)reason='Torwart vorhanden';else if(!capacity)reason='Kader voll';else if(cashAfter<0)reason='Budget reicht nicht';return{allowed:!offer.signed&&Boolean(selectedSponsor())&&allowedWindow&&keeperAllowed&&capacity&&cashAfter>=0,reason,cashAfter,newPayroll,keeperIncome}
}
function transferOfferHTML(offer){const player=offer.player,decision=offerDecision(offer),feeLabel=offer.fee?`${offer.fee} Credits`:'ablösefrei',future=decision.cashAfter-decision.newPayroll;return`<article class="market-card"><div class="market-name">${flagSVG(player.nation)}<div><b>${escapeHTML(player.name)}</b><span>${transferPosition(player)} · ${player.age} Jahre</span></div></div><p>${escapeHTML(scoutingText(player))}</p><div class="market-numbers"><span>Ablöse<b>${feeLabel}</b></span><span>Gehalt<b>${annualSalary(player)}/Jahr</b></span><span class="${future<0?'finance-danger':''}">Nach Gehältern<b>${future}</b></span></div>${player.keeper&&decision.keeperIncome?`<small>Beim Wechsel kommen ${decision.keeperIncome} Credits für deinen bisherigen Torwart hinzu.</small>`:''}<button class="menu-action wide" data-buy="${offer.id}" ${decision.allowed?'':'disabled'}>${escapeHTML(decision.reason)}</button></article>`}
function retirementHTML(state){if(!state.retirements.length)return'';return`<section class="panel retirement-panel"><p class="eyebrow">KARRIEREENDE</p><h2>${state.retirements.length===1?'Ein Spieler beendet seine Karriere.':`${state.retirements.length} Spieler beenden ihre Karriere.`}</h2><div class="retirement-list">${state.retirements.map(item=>`<div><b>${escapeHTML(item.name)}</b><span>${item.age} Jahre · ${item.careerGames} Karrierespiele</span></div>`).join('')}</div></section>`}
function ownTransferHTML(state){if(!state.open)return'';const active=activeOutfield();return`<details class="panel own-transfers"><summary><b>Eigene Spieler verkaufen</b><span>${active.length} Feldspieler</span></summary><p class="help">Verkäufe sind nur vor dem Transferschluss möglich. Mindestens fünf Feldspieler müssen bleiben.</p><div class="sale-list">${active.map(player=>{const canSell=active.length>5,amount=saleValue(player);return`<div><span>${flagSVG(player.nation)}<b>${escapeHTML(player.name)}</b><small>${transferPosition(player)} · ${annualSalary(player)} Gehalt</small></span><button class="menu-action" data-sell="${player.pid}" ${canSell?'':'disabled'}>${canSell?`+${amount} Credits`:'Mindestkader'}</button></div>`}).join('')}</div></details>`}
function transferMarketHTML(){
 const state=transferState(),regular=state.offers.filter(offer=>offer.kind==='regular'&&!offer.signed),free=state.offers.filter(offer=>offer.kind==='free'&&!offer.signed),active=activeRosterSize(),status=state.open?'OFFEN BIS ZUR KADERBESTÄTIGUNG':'GESCHLOSSEN';
 return`${retirementHTML(state)}<section class="panel transfer-panel"><div class="section-heading"><div><p class="eyebrow">TRANSFERMARKT · ${status}</p><h2>${state.open?'Kader für die neue Saison':'Ablösefreie Spieler'}</h2></div><strong>${active}/12 Spieler</strong></div>${state.notice?`<p class="transfer-notice">${escapeHTML(state.notice)}</p>`:''}${state.open?`<p class="help">Mit der Kaderbestätigung endet das reguläre Transferfenster endgültig. Danach bleiben nur ablösefreie Verpflichtungen möglich.</p><h3>Spieler mit Ablöse</h3><div class="market-grid">${regular.map(transferOfferHTML).join('')||'<p class="help">Keine regulären Angebote mehr.</p>'}</div>`:'<p class="help">Käufe und Verkäufe mit Ablöse sind beendet. Ablösefreie Spieler dürfen während der Saison verpflichtet werden.</p>'}<h3>Ablösefreie Spieler</h3><div class="market-grid">${free.map(transferOfferHTML).join('')||'<p class="help">Aktuell sind keine ablösefreien Spieler verfügbar.</p>'}</div>${state.open?`<button id="close-window" class="primary wide" ${selectedSponsor()&&validMatchSquad()?'':'disabled'}>Kader bestätigen & Transferschluss <span>↗</span></button><p class="window-check">${!selectedSponsor()?'Zuerst den Sponsor der neuen Saison wählen.':!validMatchSquad()?'Benötigt werden ein aktiver Torwart und mindestens fünf Feldspieler.':'Der Kader ist spielfähig. Nach der Bestätigung sind nur noch ablösefreie Zugänge erlaubt.'}</p>`:''}</section>${ownTransferHTML(state)}`
}
function decorateTransfers(){
 if(!activeSave||activeSave.finance?.gameOver)return;ensureTransfers(activeSave);if(activeSave.seasonNumber<2)return;const financePanel=clubCenter.querySelector('.finance-panel'),intro=clubCenter.querySelector('.intro');(financePanel||intro)?.insertAdjacentHTML('afterend',transferMarketHTML());
 const state=transferState(),lineupButton=clubCenter.querySelector('#to-lineup');if(lineupButton&&(state.open||!validMatchSquad())){lineupButton.disabled=true;lineupButton.textContent=state.open?'Zuerst Transferfenster schließen':'Kader nicht spielfähig'}
 clubCenter.querySelectorAll('[data-buy]').forEach(button=>button.onclick=()=>buyOffer(button.dataset.buy));clubCenter.querySelectorAll('[data-sell]').forEach(button=>button.onclick=()=>sellPlayer(button.dataset.sell));const close=clubCenter.querySelector('#close-window');if(close)close.onclick=closeTransferWindow;
 clubCenter.querySelectorAll('.squad-row').forEach((row,index)=>{const player=[activeSave.keeper,...activeSave.squad][index];if(player?.retired){row.className+=' retired-player';const copy=row.querySelector('div');copy?.insertAdjacentHTML('beforeend','<strong class="retired-badge">KARRIERE BEENDET</strong>');const button=row.querySelector('button');if(button)button.disabled=true}});document.querySelectorAll('footer span:first-child').forEach(element=>element.textContent='SECHSER / PROTOTYP 16')
}
function buyOffer(id){
 const state=transferState(),offer=state.offers.find(item=>item.id===id),decision=offer?offerDecision(offer):null;if(!offer||!decision?.allowed)return false;const player=structuredClone(offer.player);ensurePlayerId(player);
 if(player.keeper){const old=activeSave.keeper;if(old&&!old.retired){const income=saleValue(old);bookCredit(`sale-${state.season}-${old.pid}`,`Verkauf ${old.name}`,income,'transfer-sale');archiveFormer(old,'Transfer',income);state.history.push({type:'sale',name:old.name,amount:income,pid:old.pid})}activeSave.keeper=player;activeSave.keeper.n=1;activeSave.keeper.retired=false}else{player.n=nextSquadNumber();activeSave.squad.push(player)}
 bookCredit(`buy-${state.season}-${offer.id}`,`${offer.fee?'Transfer':'Ablösefrei'} ${player.name}`,-offer.fee,'transfer-buy');offer.signed=true;state.history.push({type:'buy',name:player.name,amount:offer.fee,pid:player.pid,free:offer.fee===0});state.notice=`${player.name} wurde verpflichtet.`;currentStats(player);normalizeLineup();syncLineupFromSquad();saveCurrent();renderCenter();return true
}
function sellPlayer(pid){
 const state=transferState(),active=activeOutfield(),index=activeSave.squad.findIndex(player=>player.pid===pid&&!player.retired);if(!state.open||!selectedSponsor()||active.length<=5||index<0)return false;const[player]=activeSave.squad.splice(index,1),amount=saleValue(player);bookCredit(`sale-${state.season}-${player.pid}`,`Verkauf ${player.name}`,amount,'transfer-sale');archiveFormer(player,'Transfer',amount);state.history.push({type:'sale',name:player.name,amount,pid:player.pid});state.notice=`${player.name} wurde für ${amount} Credits verkauft.`;normalizeLineup();syncLineupFromSquad();saveCurrent();renderCenter();return true
}
function closeTransferWindow(){
 const state=transferState();if(!state.open)return true;if(!selectedSponsor()){state.notice='Vor dem Transferschluss muss ein Sponsor gewählt werden.';renderCenter();return false}if(!validMatchSquad()){state.notice='Der Kader braucht einen aktiven Torwart und mindestens fünf Feldspieler.';renderCenter();return false}state.open=false;state.closedAtRound=activeSave.currentRound;state.notice='Das reguläre Transferfenster ist geschlossen.';activeSave.squad=activeSave.squad.filter(player=>!player.retired);normalizeLineup();syncLineupFromSquad();saveCurrent();renderCenter();return true
}

const v15Payroll=payroll;payroll=function(save=activeSave){return[save.keeper,...save.squad].filter(player=>player&&!player.retired).reduce((sum,player)=>sum+annualSalary(player),0)};
const v15EnsureChampionship=ensureChampionship;ensureChampionship=function(raw){const save=v15EnsureChampionship(raw);ensureTransfers(save);return save};
const v15RenderCenter=renderCenter;renderCenter=function(){v15RenderCenter();decorateTransfers()};
const v15ShowTactics=showTactics;showTactics=function(){const state=activeSave&&transferState();if(state?.open||!validMatchSquad()){renderCenter();return}v15ShowTactics()};
const v15Start=start;start=function(){const state=activeSave&&transferState();if(state?.open||!validMatchSquad()){if(activeSave)renderCenter();return}v15Start()};$('#start').onclick=()=>start();
const v15StartNextSeason=startNextSeason;startNextSeason=function(){const previous=activeSave?.seasonNumber;v15StartNextSeason();if(activeSave&&!activeSave.finance.gameOver&&activeSave.seasonNumber===previous+1)openTransferWindow()};
document.querySelectorAll('footer span:first-child').forEach(element=>element.textContent='SECHSER / PROTOTYP 16');
